const crypto = require('crypto');
const http = require('http');

const SECRET = crypto.randomBytes(32);
const RATE_LIMIT_WINDOW = 60000;
const MAX_REQUESTS = 100;

const sessions = new Map();
const rateLimits = new Map();

function hmacSign(data) {
  return crypto.createHmac('sha256', SECRET).update(data).digest();
}

function createToken(userId, role, permissions) {
  const payload = JSON.stringify({
    sub: userId,
    role: role,
    permissions: permissions,
    iat: Date.now(),
    exp: Date.now() + 3600000,
    jti: crypto.randomBytes(8).toString('hex')
  });
  const payloadB64 = Buffer.from(payload).toString('base64url');
  const signature = hmacSign(payloadB64);
  return payloadB64 + '.' + signature.toString('base64url');
}

function verifyToken(token) {
  if (!token || typeof token !== 'string') return null;
  const dotIndex = token.indexOf('.');
  if (dotIndex === -1) return null;

  const payloadB64 = token.substring(0, dotIndex);
  const signatureB64 = token.substring(dotIndex + 1);

  const expectedSig = hmacSign(payloadB64);
  const providedSig = Buffer.from(signatureB64, 'base64url');

  if (expectedSig.length !== providedSig.length) return null;
  if (!crypto.timingSafeEqual(expectedSig, providedSig)) return null;

  try {
    const payload = JSON.parse(Buffer.from(payloadB64, 'base64url').toString());
    if (!payload.exp || payload.exp < Date.now()) return null;
    return payload;
  } catch (e) {
    return null;
  }
}

function checkPermission(payload, requiredPermission) {
  if (!payload || !payload.permissions) return false;
  const userPerms = payload.permissions;
  const requiredBits = requiredPermission;
  // Use unsigned right shift to ensure unsigned 32-bit comparison
  return ((userPerms & requiredBits) >>> 0) === (requiredBits >>> 0);
}

function checkRateLimit(userId) {
  const now = Date.now();
  let record = rateLimits.get(userId);
  if (!record || (now - record.windowStart) > RATE_LIMIT_WINDOW) {
    record = { windowStart: now, count: 0 };
    rateLimits.set(userId, record);
  }
  record.count++;
  return record.count <= MAX_REQUESTS;
}

// Permission constants
const PERM_READ = 0x1;
const PERM_WRITE = 0x2;
const PERM_DELETE = 0x4;
const PERM_ADMIN = 0x80000000; // Bit 31 - admin flag

function createUser(username, password, role) {
  // Prevent account takeover: reject if username already exists
  if (sessions.has(username)) {
    throw new Error('Username already exists');
  }
  const salt = crypto.randomBytes(16);
  const hash = crypto.scryptSync(password, salt, 64);
  let permissions = PERM_READ;
  if (role === 'editor') permissions = PERM_READ | PERM_WRITE;
  if (role === 'admin') permissions = PERM_READ | PERM_WRITE | PERM_DELETE | PERM_ADMIN;

  const user = {
    id: crypto.randomBytes(8).toString('hex'),
    username,
    passwordHash: hash.toString('hex'),
    salt: salt.toString('hex'),
    role,
    permissions
  };
  sessions.set(username, user);
  return user;
}

function authenticateUser(username, password) {
  const user = sessions.get(username);
  if (!user) return null;
  const salt = Buffer.from(user.salt, 'hex');
  const hash = crypto.scryptSync(password, salt, 64);
  if (!crypto.timingSafeEqual(hash, Buffer.from(user.passwordHash, 'hex'))) {
    return null;
  }
  return createToken(user.id, user.role, user.permissions);
}

const server = http.createServer((req, res) => {
  let body = '';
  req.on('data', chunk => body += chunk);
  req.on('end', () => {
    try {
      const url = new URL(req.url, 'http://localhost');

      if (url.pathname === '/register' && req.method === 'POST') {
        const { username, password, role } = JSON.parse(body);
        if (!username || !password || password.length < 12) {
          res.writeHead(400); res.end('Invalid input'); return;
        }
        // Only allow 'user' and 'editor' roles for self-registration
        const safeRole = (role === 'editor') ? 'editor' : 'user';
        let user;
        try {
          user = createUser(username, password, safeRole);
        } catch (err) {
          res.writeHead(409); res.end('Username already exists'); return;
        }
        const token = createToken(user.id, user.role, user.permissions);
        res.writeHead(200, {'Content-Type':'application/json'});
        res.end(JSON.stringify({ token }));
        return;
      }

      if (url.pathname === '/login' && req.method === 'POST') {
        const { username, password } = JSON.parse(body);
        const token = authenticateUser(username, password);
        if (!token) { res.writeHead(401); res.end('Unauthorized'); return; }
        res.writeHead(200, {'Content-Type':'application/json'});
        res.end(JSON.stringify({ token }));
        return;
      }

      if (url.pathname === '/admin/users' && req.method === 'GET') {
        const token = req.headers['authorization']?.replace('Bearer ', '');
        const payload = verifyToken(token);
        if (!payload) { res.writeHead(401); res.end('Unauthorized'); return; }
        if (!checkRateLimit(payload.sub)) { res.writeHead(429); res.end('Rate limited'); return; }
        // Require admin permission
        if (!checkPermission(payload, PERM_ADMIN)) {
          res.writeHead(403); res.end('Forbidden'); return;
        }
        const users = Array.from(sessions.values()).map(u => ({
          id: u.id, username: u.username, role: u.role
        }));
        res.writeHead(200, {'Content-Type':'application/json'});
        res.end(JSON.stringify(users));
        return;
      }

      if (url.pathname === '/documents' && req.method === 'DELETE') {
        const token = req.headers['authorization']?.replace('Bearer ', '');
        const payload = verifyToken(token);
        if (!payload) { res.writeHead(401); res.end('Unauthorized'); return; }
        if (!checkRateLimit(payload.sub)) { res.writeHead(429); res.end('Rate limited'); return; }
        if (!checkPermission(payload, PERM_DELETE)) {
          res.writeHead(403); res.end('Forbidden'); return;
        }
        res.writeHead(200); res.end('Deleted');
        return;
      }

      res.writeHead(404); res.end('Not found');
    } catch(e) {
      res.writeHead(500); res.end('Internal error');
    }
  });
});

server.listen(3000);
module.exports = { createToken, verifyToken, checkPermission, createUser, authenticateUser, PERM_READ, PERM_WRITE, PERM_DELETE, PERM_ADMIN };
